public void ResetTalent()
	{
		if (!(GameWorld.instance.PlayerProfile.GetResourceQuantity(ResourceType.PracticePoints) >= (double)GetTalentResetCost()))
		{
			return;
		}
		GameWorld.instance.PlayerProfile.BatchResourceUpdate(new List<ResourceUpdate>
		{
			new ResourceUpdate
			{
				ResourceType = ResourceType.PracticePoints,
				ChangeAmount = -GetTalentResetCost(),
				RelatedItems = new List<Item>()
			}
		});
		foreach (IAdventurerTalent talent in Talents)
		{
			talent.Reset(this);
		}
		TalentPoints = GetLevel() / 5;
		if (TalentPoints > 17)
		{
			TalentPoints = 17;
		}
	}

public void Equip(Item item)
	{
		if (!GameWorld.instance.PlayerProfile.Items.Any((Item i) => i == item))
		{
			return;
		}
		Item item2 = null;
		if (item.Type.GetResourceCategory() == ResourceCategory.Accessory)
		{
			item2 = EquippedItems.FirstOrDefault((Item i) => i.Type.GetResourceCategory() == ResourceCategory.Accessory);
		}
		if (item.Type.GetResourceCategory() == ResourceCategory.Scrolls)
		{
			item2 = EquippedItems.FirstOrDefault((Item i) => i.Type.GetResourceCategory() == ResourceCategory.Scrolls);
		}
		if (item.Type.GetResourceCategory() == ResourceCategory.Amulet)
		{
			item2 = EquippedItems.FirstOrDefault((Item i) => i.Type.GetResourceCategory() == ResourceCategory.Amulet);
		}
		if (item.Type.GetResourceCategory() == ResourceCategory.Device)
		{
			item2 = EquippedItems.FirstOrDefault((Item i) => i.Type.GetResourceCategory() == ResourceCategory.Device);
		}
		if (item.Type.GetResourceCategory().IsWeapon())
		{
			item2 = EquippedItems.FirstOrDefault((Item i) => i.Type.GetResourceCategory().IsWeapon());
		}
		if (item.Type.GetResourceCategory().IsArmor())
		{
			item2 = EquippedItems.FirstOrDefault((Item i) => i.Type.GetResourceCategory().IsArmor());
		}
		if (item2 != null)
		{
			Disrobe(item2, needsRecache: false);
		}
		ItemStatus itemStatus = item.ItemStatus;
		EquippedItems.Add(item);
		item.SetOwner(this);
		GameWorld.instance.PlayerProfile.Items.Remove(item);
		item.ItemStatus = ItemStatus.Equipped;
		ItemStatus itemStatus2 = item.ItemStatus;
		ItemStatusUpdateEvent itemStatusUpdateEvent = new ItemStatusUpdateEvent();
		itemStatusUpdateEvent.Item = item;
		itemStatusUpdateEvent.CurrentStatus = itemStatus2;
		itemStatusUpdateEvent.PreviousStatus = itemStatus;
		ItemStatusUpdateEvent data = itemStatusUpdateEvent;
		CalculateCachedAttributeValues();
		GameWorld.instance.PlayerProfile.ReceiveEvent(GameWorldEvent.ItemEquipped, data);
		OnItemEquipped(item);
	}

public void Disrobe(Item equipment, bool needsRecache)
	{
		ItemStatus itemStatus = equipment.ItemStatus;
		equipment.ItemStatus = ItemStatus.Reserved;
		ItemStatus itemStatus2 = equipment.ItemStatus;
		ItemStatusUpdateEvent itemStatusUpdateEvent = new ItemStatusUpdateEvent();
		itemStatusUpdateEvent.Item = equipment;
		itemStatusUpdateEvent.CurrentStatus = itemStatus2;
		itemStatusUpdateEvent.PreviousStatus = itemStatus;
		ItemStatusUpdateEvent data = itemStatusUpdateEvent;
		if (EquippedItems.Any((Item i) => i == equipment))
		{
			EquippedItems.Remove(equipment);
			equipment.SetOwner(null);
			if (GameWorld.instance.PlayerProfile.Items.All((Item i) => i != equipment))
			{
				GameWorld.instance.PlayerProfile.Items.Add(equipment);
			}
		}
		GameWorld.instance.PlayerProfile.ReceiveEvent(GameWorldEvent.ItemReserved, data);
		if (needsRecache)
		{
			CalculateCachedAttributeValues();
		}
		OnItemDisrobed(equipment);
	}

private void CollectsExp(long expPoints)
	{
		if (!CurrentExperienceAdd35.HasValue)
		{
			CurrentExperienceAdd35 = Experience + 35;
		}
		if (!CurrentExperienceMultiply3.HasValue)
		{
			CurrentExperienceMultiply3 = Experience * 3;
		}
		long experience = Experience;
		long? num = CurrentExperienceAdd35 - 35;
		if (experience == num.GetValueOrDefault() && num.HasValue && Experience == CurrentExperienceMultiply3 / 3)
		{
			long experience2 = Experience;
			long num2 = Experience + expPoints;
			UnitLevelConfiguration adventurerLevelConfig = UnitExtensions.GetAdventurerLevelConfig(experience2);
			OnReceivesExp(adventurerLevelConfig, experience2, num2);
			bool flag = UnitExtensions.CanAdventurerLevelUp(experience2, num2);
			Experience = num2;
			CurrentExperienceAdd35 = num2 + 35;
			CurrentExperienceMultiply3 = num2 * 3;
			if (flag)
			{
				LevelUpLogic(experience2, num2);
			}
			List<ResourceUpdate> list = new List<ResourceUpdate>();
			list.Add(new ResourceUpdate
			{
				ResourceType = ResourceType.PracticePoints,
				ChangeAmount = -expPoints,
				RelatedItems = new List<Item>()
			});
			List<ResourceUpdate> changes = list;
			GameWorld.instance.PlayerProfile.BatchResourceUpdate(changes);
		}
	}

