private void LevelUpLogic(long fromExp, long toExp)
	{
		UnitLevelConfiguration adventurerLevelConfig = UnitExtensions.GetAdventurerLevelConfig(fromExp);
		UnitLevelConfiguration adventurerLevelConfig2 = UnitExtensions.GetAdventurerLevelConfig(toExp);
		int num = adventurerLevelConfig2.Level - adventurerLevelConfig.Level;
		AdventurerUnitConfigurationBase adventurerUnitConfigurationBase = UnitClass.GetConfiguration() as AdventurerUnitConfigurationBase;
		for (int i = 1; i <= num; i++)
		{
			int num2 = adventurerLevelConfig.Level + i;
			if (num2 % 5 == 0 && num2 <= 85)
			{
				TalentPoints++;
			}
		}
		if (adventurerLevelConfig.Level < 15 && adventurerLevelConfig2.Level >= 15)
		{
			SpecialEffects.Add(new ElementEffectData
			{
				IsStarEf = false,
				ElementType = OutputType
			});
		}
		if (adventurerLevelConfig.Level < 30 && adventurerLevelConfig2.Level >= 30)
		{
			SpecialEffects.AddRange((from o in UnitExtensions.GetAllDamageElements()
				where o != OutputType
				select new ElementEffectData
				{
					IsStarEf = false,
					ElementType = o
				}).Cast<ISpecialEffectDataLoad>());
		}
		for (int num3 = 0; num3 < num; num3++)
		{
			UnitLevelUpChange levelUpChange = adventurerUnitConfigurationBase.AdventurerGrowthProfile.GetLevelUpChange(1.0 + QualityCoefficient, 1.2);
			foreach (LevelUpChangeValue changedValue in levelUpChange.ChangedValues)
			{
				NakedAttributes = GetNakedAttributes().AddValue(changedValue.AttributeType, changedValue.Value);
			}
			CalculateCachedAttributeValues();
			if (num <= 1)
			{
				OnLevelUp(GetLevel(), adventurerLevelConfig.Level + num3 + 1, levelUpChange);
			}
		}
	}

