public List<JourneyContributionModifier> GetContributions()
	{
		double value = this.GetOutputCapacity(AttributeRetrievalLevel.Skill).Value;
		double num = this.GetAttributeValue_Final(AttributeType.CritRate, AttributeRetrievalLevel.Skill);
		if (num > 1.0)
		{
			num = 1.0;
		}
		double attributeValue_Final = this.GetAttributeValue_Final(AttributeType.CritDamage, AttributeRetrievalLevel.Skill);
		value = value * (1.0 + num) * attributeValue_Final;
		double num2 = value / (value + 4000.0);
		double num3 = UnitExtensions.GetAllResistances().Sum((AttributeType r) => this.GetAttributeValue_Final(r, AttributeRetrievalLevel.Skill)) / Convert.ToDouble(UnitExtensions.GetAllResistances().Count);
		double num4 = num3 / (num3 + 3000.0);
		double attributeValue_Final2 = this.GetAttributeValue_Final(AttributeType.Vitality, AttributeRetrievalLevel.Skill);
		double num5 = attributeValue_Final2 / (attributeValue_Final2 + 3000.0);
		double num6 = (num4 + num5) / 2.0;
		double attributeValue_Final3 = this.GetAttributeValue_Final(AttributeType.Agility, AttributeRetrievalLevel.Skill);
		double num7 = attributeValue_Final3 / (attributeValue_Final3 + 3000.0);
		double value2 = (num2 + num6 + num7) * 100.0;
		List<JourneyContributionModifier> list = new List<JourneyContributionModifier>();
		list.Add(new JourneyContributionModifier
		{
			Value = value2,
			Key = string.Empty,
			Type = JourneyContributeType.BattleSkill
		});
		return list;
	}

