public DropTable GetStandardDropableCompleteTable()
	{
		DropTable dropTable = new DropTable(new List<DropTableParameter>());
		dropTable.DropTableParameters.AddRange(from r in GetRawResources()
			select GetDefaultDropParameter(r));
		List<ResourceType> allDropableGems = GetAllDropableGems();
		foreach (ResourceType item in allDropableGems)
		{
			dropTable.DropTableParameters.Add(GetDefaultDropParameter(item, GemTier));
		}
		dropTable.DropTableParameters.AddRange(from r in GetDifficultyRelatedWeaponRecipes(new List<ResourceSourceType> { ResourceSourceType.DungeonDrop })
			select GetDefaultDropParameter(r));
		dropTable.DropTableParameters.AddRange(from r in GetDifficultyRelatedArmorRecipes(new List<ResourceSourceType> { ResourceSourceType.DungeonDrop })
			select GetDefaultDropParameter(r));
		dropTable.DropTableParameters.AddRange(from a in GetDifficultyRelatedGears(new List<ResourceSourceType> { ResourceSourceType.DungeonDrop })
			select GetDefaultDropParameter(a));
		dropTable.DropTableParameters.Add(GetDefaultDropParameter(ResourceType.PracticePoints));
		if (StarRating == -1)
		{
			dropTable.DropTableParameters.Add(GetDefaultDropParameter(ResourceType.AshOfHope));
		}
		return dropTable;
	}

private int GetLevelOneMaterialDropAmount()
	{
		if (StarRating == 1)
		{
			double num = 20.0 + DifficultyValue * 2.0;
			if (num > 150.0)
			{
				num = 150.0;
			}
			return (int)num;
		}
		return 0;
	}

private int GetLevelTwoMaterialDropAmount()
	{
		if (StarRating == 1)
		{
			if (DifficultyValue > 100.0)
			{
				double num = 5.0 + Math.Floor((DifficultyValue - 100.0) / 2.0);
				if (num > 50.0)
				{
					num = 50.0;
				}
				return (int)num;
			}
			return 0;
		}
		double num2 = 50.0 + DifficultyValue;
		if (num2 > 150.0)
		{
			num2 = 150.0;
		}
		return (int)num2;
	}

public DropTableParameter GetDefaultDropParameter(ResourceType resourceType, int level = 1)
	{
		ResourceCategory resourceCategory = resourceType.GetResourceCategory();
		if (resourceCategory == ResourceCategory.Hides || resourceCategory == ResourceCategory.Timber || resourceCategory == ResourceCategory.Ore)
		{
			switch (resourceType)
			{
			case ResourceType.Wood:
			case ResourceType.Ore:
			case ResourceType.Leather:
			{
				int levelOneMaterialDropAmount = GetLevelOneMaterialDropAmount();
				DropTableParameter dropTableParameter = new DropTableParameter();
				dropTableParameter.ResourceType = resourceType;
				dropTableParameter.Presence = 100;
				dropTableParameter.InclusiveVolumFrom = levelOneMaterialDropAmount;
				dropTableParameter.InclusiveVolumTo = levelOneMaterialDropAmount;
				return dropTableParameter;
			}
			case ResourceType.RefinedOre:
			case ResourceType.RefinedLeather:
			{
				int levelTwoMaterialDropAmount = GetLevelTwoMaterialDropAmount();
				DropTableParameter dropTableParameter = new DropTableParameter();
				dropTableParameter.ResourceType = resourceType;
				dropTableParameter.Presence = 100;
				dropTableParameter.InclusiveVolumFrom = levelTwoMaterialDropAmount;
				dropTableParameter.InclusiveVolumTo = levelTwoMaterialDropAmount;
				return dropTableParameter;
			}
			}
		}
		switch (resourceCategory)
		{
		case ResourceCategory.Gem:
		{
			DropTableParameter dropTableParameter = new DropTableParameter();
			dropTableParameter.ResourceType = resourceType;
			dropTableParameter.Level = level;
			dropTableParameter.Presence = 100;
			dropTableParameter.InclusiveVolumTo = 1.0;
			dropTableParameter.InclusiveVolumFrom = 1.0;
			return dropTableParameter;
		}
		case ResourceCategory.Usable:
		{
			DropTableParameter dropTableParameter;
			if (resourceType == ResourceType.AllSocketBatcher)
			{
				dropTableParameter = new DropTableParameter();
				dropTableParameter.ResourceType = resourceType;
				dropTableParameter.Level = level;
				dropTableParameter.Presence = 10;
				dropTableParameter.InclusiveVolumTo = 1.0;
				dropTableParameter.InclusiveVolumFrom = 1.0;
				return dropTableParameter;
			}
			dropTableParameter = new DropTableParameter();
			dropTableParameter.ResourceType = resourceType;
			dropTableParameter.Level = level;
			dropTableParameter.Presence = 100;
			dropTableParameter.InclusiveVolumTo = 1.0;
			dropTableParameter.InclusiveVolumFrom = 1.0;
			return dropTableParameter;
		}
		case ResourceCategory.ProductionRecipe:
		{
			DropTableParameter dropTableParameter = new DropTableParameter();
			dropTableParameter.ResourceType = resourceType;
			dropTableParameter.Presence = resourceType.GetRecipeByRecipeName().ProductType.GetCreationTemplate().DefaultRecipeDropPresences;
			dropTableParameter.InclusiveVolumFrom = 1.0;
			dropTableParameter.InclusiveVolumTo = 1.0;
			return dropTableParameter;
		}
		case ResourceCategory.Accessory:
		{
			DropTableParameter dropTableParameter = new DropTableParameter();
			dropTableParameter.ResourceType = resourceType;
			dropTableParameter.Presence = resourceType.GetCreationTemplate().DefaultItemDropPresences;
			dropTableParameter.InclusiveVolumTo = 1.0;
			dropTableParameter.InclusiveVolumFrom = 1.0;
			return dropTableParameter;
		}
		default:
			if (resourceCategory.IsWeapon() || resourceCategory.IsArmor())
			{
				DropTableParameter dropTableParameter = new DropTableParameter();
				dropTableParameter.ResourceType = resourceType;
				dropTableParameter.Presence = resourceType.GetCreationTemplate().DefaultItemDropPresences;
				dropTableParameter.InclusiveVolumTo = 1.0;
				dropTableParameter.InclusiveVolumFrom = 1.0;
				return dropTableParameter;
			}
			switch (resourceType)
			{
			case ResourceType.PracticePoints:
			{
				double num2 = GetPracticePointsPerGain((StarRating != 1) ? (DifficultyValue + 200.0) : DifficultyValue);
				if (num2 > 4000.0)
				{
					num2 = 4000.0;
				}
				double num3 = GameWorld.instance.PlayerProfile.GetTownStats().TotalPracticePointsBoost + 1.0;
				DropTableParameter dropTableParameter = new DropTableParameter();
				dropTableParameter.ResourceType = resourceType;
				dropTableParameter.Level = 1;
				dropTableParameter.Presence = 100;
				dropTableParameter.InclusiveVolumTo = num2 * num3;
				dropTableParameter.InclusiveVolumFrom = num2 * num3;
				return dropTableParameter;
			}
			case ResourceType.AshOfHope:
			{
				int num = ((StarRating == -1) ? (5 + (int)Math.Floor(DifficultyValue / 4.0)) : 0);
				DropTableParameter dropTableParameter = new DropTableParameter();
				dropTableParameter.ResourceType = resourceType;
				dropTableParameter.Level = 1;
				dropTableParameter.Presence = 100;
				dropTableParameter.InclusiveVolumTo = num;
				dropTableParameter.InclusiveVolumFrom = num;
				return dropTableParameter;
			}
			default:
				throw new NotImplementedException();
			}
		}
	}

public double GetPracticePointsPerGain(double difficultyValue)
	{
		if (StarRating == 1)
		{
			if (difficultyValue <= 20.0)
			{
				return difficultyValue * 80.0 + 300.0;
			}
			if (difficultyValue <= 40.0)
			{
				return (difficultyValue - 20.0) * 50.0 + 1900.0;
			}
			if (difficultyValue <= 60.0)
			{
				return (difficultyValue - 40.0) * 20.0 + 2900.0;
			}
			if (difficultyValue <= 100.0)
			{
				return (difficultyValue - 60.0) * 10.0 + 3300.0;
			}
			if (difficultyValue <= 150.0)
			{
				return (difficultyValue - 100.0) * 5.0 + 3700.0;
			}
			return 4000.0;
		}
		if (StarRating == 2)
		{
			if (difficultyValue <= 50.0)
			{
				return 4000.0 + 20.0 * difficultyValue;
			}
			if (difficultyValue <= 150.0)
			{
				return 5000.0 + 10.0 * (difficultyValue - 50.0);
			}
			return 6000.0;
		}
		return 7000.0;
	}

