public List<ResourceUpdate> GenerateAccessories(int volum, QualityGrade? grade = null, bool forceStar = false)
	{
		List<DropTableParameter> list = (from t in GetDifficultyRelatedAccessories()
			select new DropTableParameter
			{
				ResourceType = t,
				Presence = 100,
				Level = 1,
				InclusiveVolumTo = 1.0,
				InclusiveVolumFrom = 1.0
			}).ToList();
		if (forceStar)
		{
			list = list.Where((DropTableParameter p) => p.ResourceType.GetCreationTemplate() is AccessoryTemplateBase && (p.ResourceType.GetCreationTemplate() as AccessoryTemplateBase).GenerateStarEffects(QualityGrade.Ancient, GetCorrespondingItemTierLevel(p.ResourceType)).Any()).ToList();
		}
		List<DropTableParameter> list2 = list.WeightedRandomSelectMaxUniqueness((DropTableParameter a, DropTableParameter b) => a.ResourceType == b.ResourceType, volum);
		List<ResourceUpdate> list3 = new List<ResourceUpdate>();
		foreach (DropTableParameter item2 in list2)
		{
			if (item2.ResourceType.GetCreationTemplate() is AccessoryTemplateBase accessoryTemplateBase)
			{
				if (forceStar && !accessoryTemplateBase.GenerateStarEffects(QualityGrade.Ancient, GetCorrespondingItemTierLevel(accessoryTemplateBase.ItemType)).Any())
				{
					forceStar = false;
				}
				ResourceType resourceType = item2.ResourceType;
				ResourceSourceType itemSource = ResourceSourceType.DungeonDrop;
				int correspondingItemTierLevel = GetCorrespondingItemTierLevel(item2.ResourceType);
				Item item = resourceType.ItemGenerate(itemSource, GetQualityConfig(grade, ResourceSourceType.DungeonDrop, item2.ResourceType, forceStar), correspondingItemTierLevel);
				list3.Add(new ResourceUpdate
				{
					ResourceType = item.Type,
					ChangeAmount = 1.0,
					RelatedItems = new List<Item> { item }
				});
			}
		}
		return list3;
	}

