		List<ResourceType> list;
		if (StarRating == 1)
		{
			if (DifficultyValue <= 100.0)
			{
				list = new List<ResourceType>();
				list.Add(ResourceType.Ore);
				list.Add(ResourceType.Leather);
				return list;
			}
			list = new List<ResourceType>();
			list.Add(ResourceType.RefinedOre);
			list.Add(ResourceType.RefinedLeather);
			list.Add(ResourceType.Ore);
			list.Add(ResourceType.Leather);
			return list;
		}
		list = new List<ResourceType>();
		list.Add(ResourceType.RefinedOre);
		list.Add(ResourceType.RefinedLeather);
		return list;
	}

