public static Dictionary<AttributeRetrievalLevel, Dictionary<AttributeType, Dictionary<ModificationType, double?>>> GetValues(this List<AttributeModifier> modifiers)
	{
		Dictionary<AttributeRetrievalLevel, Dictionary<AttributeType, Dictionary<ModificationType, double?>>> dictionary = new Dictionary<AttributeRetrievalLevel, Dictionary<AttributeType, Dictionary<ModificationType, double?>>>();
		List<AttributeModifier> modifiers2 = modifiers.Where((AttributeModifier m) => m.AttributeModifierType == AttributeModifierType.Normal).ToList();
		RetrieveValues(AttributeRetrievalLevel.Naked, modifiers2, dictionary);
		List<AttributeModifier> modifiers3 = modifiers.Where((AttributeModifier a) => a.AttributeModifierType == AttributeModifierType.Gear || a.AttributeModifierType == AttributeModifierType.Embeded || a.AttributeModifierType == AttributeModifierType.Growth).ToList();
		RetrieveValues(AttributeRetrievalLevel.Gear, modifiers3, dictionary);
		List<AttributeModifier> modifiers4 = modifiers.Where((AttributeModifier a) => a.AttributeModifierType == AttributeModifierType.SetBonus).ToList();
		RetrieveValues(AttributeRetrievalLevel.Bonus, modifiers4, dictionary);
		return dictionary;
	}

private static void RetrieveValues(AttributeRetrievalLevel level, List<AttributeModifier> modifiers, Dictionary<AttributeRetrievalLevel, Dictionary<AttributeType, Dictionary<ModificationType, double?>>> values)
	{
		values[level] = new Dictionary<AttributeType, Dictionary<ModificationType, double?>>();
		foreach (AttributeType allAttributeType in ItemExtensions.AllAttributeTypes)
		{
			AttributeType type = allAttributeType;
			List<AttributeModifier> source = modifiers.Where((AttributeModifier a) => a.AttributeType == type).ToList();
			values[level][type] = new Dictionary<ModificationType, double?>();
			values[level][type][ModificationType.Addition] = source.Where((AttributeModifier a) => a.ModificationType == ModificationType.Addition).Sum((AttributeModifier a) => a.Value);
			values[level][type][ModificationType.Multiplication] = source.Where((AttributeModifier a) => a.ModificationType == ModificationType.Multiplication).Sum((AttributeModifier a) => a.Value);
			List<AttributeModifier> source2 = source.Where((AttributeModifier a) => a.ModificationType == ModificationType.Replacement).ToList();
			if (source2.Any())
			{
				values[level][type][ModificationType.Replacement] = source2.Last().Value;
			}
			else
			{
				values[level][type][ModificationType.Replacement] = null;
			}
		}
	}

