	{
		int num = 150;
		int num2 = 100;
		int num3 = 10000;
		int num4 = -1;
		List<UnitLevelConfiguration> list = new List<UnitLevelConfiguration>();
		for (int i = 0; i <= 91; i++)
		{
			list.Add(new UnitLevelConfiguration
			{
				Level = i + 1,
				FromExp = num4 + 1,
				ToExp = num4 + num
			});
			num4 += num;
			if (i < 59)
			{
